const result = $input.first().json.stdout;
if (!result) return [];
const lines = result.split('\n').filter(l => l.trim() !== '');
const EXT = /\.(jpg|jpeg|png|webp|gif)$/i;

function normalizeName(str) {
  if (!str) return '';
  return String(str).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]/g, '');
}

const out = [];
for (const fullPath of lines) {
  if (!EXT.test(fullPath)) continue;

  const parts = fullPath.split('/');
  const fileName = parts.pop();
  const categoryRaw = parts.pop();

  if (!categoryRaw) continue;

  const category = normalizeName(categoryRaw);
  const baseName = fileName.replace(/\.[^.]+$/i, '');
  const matchKey = normalizeName(baseName);
  const compositeKey = matchKey + '|' + category;

  out.push({ 
    json: { 
      path: fullPath, 
      fileName, 
      categoryRaw, 
      category, 
      matchKey, 
      compositeKey 
    } 
  });
}

return out;

const items = $input.all();
const cleaned = [];

const COL = { 
  codigo: 'CÓDIGO', 
  nombre: 'NOMBRE', 
  precioUsd: 'PRECIO USD', 
  precioCup: 'PRECIO CUP', 
  estado: 'ESTADO' 
};

function safeNum(val) {
  if (val === null || val === undefined) return null;
  if (typeof val === 'number' && !Number.isNaN(val)) return val;
  const s = String(val).replace(/[^0-9.,]/g, '').replace(',', '.');
  const n = parseFloat(s);
  return Number.isNaN(n) ? null : n;
}

function safeStr(val) {
  if (val === null || val === undefined) return '';
  return String(val).trim();
}

function normalizeName(str) {
  if (!str) return '';
  return String(str).normalize("NFD").replace(/[\u0300-\u036f]/g, "").toUpperCase().replace(/[^A-Z0-9]/g, '');
}

function isSectionHeader(codigo, nombre) {
  const c = String(codigo).trim();
  const n = safeStr(nombre);
  return c.includes('---') || (!n && !c);
}

function sectionToCategory(codigo) {
  const m = String(codigo).match(/---\s*([^---]+)\s*---/);
  return m ? normalizeName(m[1]) : null;
}

let currentCategory = '';

for (const item of items) {
  const row = item.json || item;

  const codigoRaw = row[COL.codigo];
  const nombre = safeStr(row[COL.nombre]);
  const usd = safeNum(row[COL.precioUsd]);
  const cup = safeNum(row[COL.precioCup]);

  if (isSectionHeader(codigoRaw, nombre)) {
    const cat = sectionToCategory(codigoRaw);
    if (cat) currentCategory = cat;
    continue;
  }

  if (!nombre) continue;

  const matchKey = normalizeName(nombre);
  if (!matchKey) continue;

  const category = currentCategory || 'GENERAL';
  const compositeKey = matchKey + '|' + category;

  cleaned.push({
    json: {
      matchKey,
      category,
      compositeKey,
      codigo: codigoRaw,
      productId: nombre,
      usdPrice: usd,
      cupPrice: cup,
      usdFormatted: usd != null ? `$${Number(usd).toFixed(2)} USD` : '',
      cupFormatted: cup != null ? `${Number(cup).toLocaleString('en-US')} CUP` : ''
    }
  });
}

return cleaned;

function levenshtein(a, b) {
  if (a.length === 0) return b.length;
  if (b.length === 0) return a.length;
  const matrix = [];
  for (let i = 0; i <= b.length; i++) { matrix[i] = [i]; }
  for (let j = 0; j <= a.length; j++) { matrix[0][j] = j; }
  for (let i = 1; i <= b.length; i++) {
    for (let j = 1; j <= a.length; j++) {
      if (b.charAt(i - 1) === a.charAt(j - 1)) {
        matrix[i][j] = matrix[i - 1][j - 1];
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j - 1] + 1,
          Math.min(matrix[i][j - 1] + 1, matrix[i - 1][j] + 1)
        );
      }
    }
  }
  return matrix[b.length][a.length];
}

const unmatchedFiles = $input.all();
if (!unmatchedFiles || unmatchedFiles.length === 0) return [];

const allProducts = $node["CleanPricing"].all();
const recovered = [];

for (const file of unmatchedFiles) {
  const fileKey = file.json.matchKey || "";
  if (!fileKey) continue;

  let bestMatch = null;
  let bestSimilarity = 0;

  for (const product of allProducts) {
    const prodKey = product.json.matchKey || "";
    if (!prodKey) continue;

    const distance = levenshtein(fileKey, prodKey);
    const maxLength = Math.max(fileKey.length, prodKey.length);
    const similarity = maxLength === 0 ? 1 : (maxLength - distance) / maxLength;

    if (similarity >= 0.8 && similarity > bestSimilarity) {
      bestSimilarity = similarity;
      bestMatch = product.json;
    }
  }

  if (bestMatch) {
    recovered.push({
      json: {
        ...bestMatch,
        path: file.json.path,
        fileName: file.json.fileName,
        categoryRaw: file.json.categoryRaw
      }
    });
  }
}

return recovered;
